def solve(grid):
    """Fill cells that have BOTH a marker to left/right AND a marker to up/down"""
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])

    # Find 9s (markers)
    nines = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 9:
                nines.add((r, c))

    result = [row[:] for row in grid]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1:
                # Check ALL directions for a 9
                dirs = [(-1,0), (1,0), (0,-1), (0,1)]  # up, down, left, right
                found_any = False
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    path_found = False
                    while True:
                        if not (0 <= nr < H and 0 <= nc < W):
                            break
                        if (nr, nc) in nines:
                            path_found = True
                            break
                        nr, nc = nr + dr, nc + dc

                    if path_found:
                        found_any = True

                # Convert ONLY if found in ALL 4 directions (or at least 2?)
                if found_any:
                    result[r][c] = 3

    return result

