# Let me try BFS from ALL positions that CAN reach a 9 in all 4 directions via 1s
def solve(grid):
    """Fill cells that can reach a 9 in each of 4 directions using only 1s"""
    if not grid or not grid[0]:
        return grid

    H, W = len(grid), len(grid[0])

    # Find 9s (markers)
    nines = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 9:
                nines.add((r, c))

    result = [row[:] for row in grid]

    for start_r in range(H):
        for start_c in range(W):
            if grid[start_r][start_c] == 1:
                # Check if we can go up to find a 9 (only through 1s)
                can_go_up = False
                rr, cc = start_r, start_c
                while rr > 0:
                    rr -= 1
                    if grid[rr][cc] == 9:
                        can_go_up = True
                        break
                    if grid[rr][cc] != 1:
                        break

                # Can go down
                can_go_down = False
                rr, cc = start_r, start_c
                while rr < H - 1:
                    rr += 1
                    if grid[rr][cc] == 9:
                        can_go_down = True
                        break
                    if grid[rr][cc] != 1:
                        break

                # Can go left
                can_go_left = False
                rr, cc = start_r, start_c
                while cc > 0:
                    cc -= 1
                    if grid[rr][cc] == 9:
                        can_go_left = True
                        break
                    if grid[rr][cc] != 1:
                        break

                # Can go right
                can_go_right = False
                rr, cc = start_r, start_c
                while cc < W - 1:
                    cc += 1
                    if grid[rr][cc] == 9:
                        can_go_right = True
                        break
                    if grid[rr][cc] != 1:
                        break

                # Fill if can reach 9 in ALL 4 directions
                if can_go_up and can_go_down and can_go_left and can_go_right:
                    result[start_r][start_c] = 3

    return result

